734	### `src/sim/teams.ts`
735	
736	```ts
737	/**
738	 * Lobby, teams and roles. Pure functions: every call returns a new Lobby and
739	 * the list of people it moved, so the host UI can toast "Marco -> Verde".
740	 *
741	 * Invariants:
742	 *  - a player is in exactly one place: one team's member list or the spectator queue.
743	 *  - role = index in the member list: 0 Pilot, 1 Gunner, 2 Engineer.
744	 *  - after every change the team sizes are the balanced multiset for the
745	 *    active player count (7 in threes is 3+2+2, never 3+3+1).
746	 */
747	import { CONFIG } from '@shared/config.ts';
748	import type { PlayerState, Role, TeamSize } from '@shared/state.ts';
749	import { ROLES } from '@shared/state.ts';
750	
751	export type LobbyPlayer = Pick<
752	  PlayerState,
753	  'id' | 'name' | 'joinOrder' | 'pinned' | 'connected' | 'enabled' | 'ready' | 'calibrated' | 'kind'
754	>;
755	
756	export interface Lobby {
757	  teamSize: TeamSize;
758	  /** teams[i] = player ids in role order. */
759	  teams: string[][];
760	  players: Record<string, LobbyPlayer>;
761	  /** Join-order queue beyond capacity. */
762	  spectators: string[];
763	}
764	
765	export interface Move {
766	  id: string;
767	  /** Team index before, null = spectators or new. */
768	  from: number | null;
769	  /** Team index after (final numbering), null = spectators. */
770	  to: number | null;
771	}
772	
773	export interface LobbyChange {
774	  lobby: Lobby;
775	  moves: Move[];
776	  /** Some surviving team changed its index (and therefore its colour). */
777	  renumbered: boolean;
778	}
779	
780	export interface Slot {
781	  team: number;
782	  role: Role;
783	  index: number;
784	}
785	
786	/** What one phone has to show. Merged roles for short-handed teams. */
787	export interface ControlSet {
788	  steer: boolean;
789	  gas: boolean;
790	  aim: boolean;
791	  fire: boolean;
792	  powers: boolean;
793	  bail: boolean;
794	  /** 1-person team: auto-throttle and auto-target FIRE (stretch). */
795	  solo: boolean;
796	}
797	
798	const MAX_TEAMS = CONFIG.teams.maxTeams;
799	
800	export function capacity(size: TeamSize, maxTeams: number = MAX_TEAMS): number {
801	  return size * maxTeams;
802	}
803	
804	/** Number of teams for n active players: min(6, ceil(n / size)). */
805	export function teamCount(n: number, size: TeamSize, maxTeams: number = MAX_TEAMS): number {
806	  if (n <= 0) return 0;
807	  return Math.min(maxTeams, Math.ceil(n / size));
808	}
809	
810	/**
811	 * Balanced sizes, largest first: base = floor(n / t), the first (n mod t) teams get one more.
812	 * Players beyond capacity are not counted (they are spectators).
813	 */
814	export function targetSizes(n: number, size: TeamSize, maxTeams: number = MAX_TEAMS): number[] {
815	  const active = Math.min(Math.max(0, n), capacity(size, maxTeams));
816	  const t = teamCount(active, size, maxTeams);
817	  if (t === 0) return [];
818	  const base = Math.floor(active / t);
819	  const extra = active % t;
820	  const out: number[] = [];
821	  for (let i = 0; i < t; i++) out.push(base + (i < extra ? 1 : 0));
822	  return out;
823	}
824	
825	export function balanceTable(size: TeamSize, upTo: number = 18): { n: number; sizes: number[]; spectators: number }[] {
826	  const rows: { n: number; sizes: number[]; spectators: number }[] = [];
827	  for (let n = 1; n <= upTo; n++) {
828	    rows.push({ n, sizes: targetSizes(n, size), spectators: Math.max(0, n - capacity(size)) });
829	  }
830	  return rows;
831	}
832	
833	export function createLobby(teamSize: TeamSize = CONFIG.teams.defaultTeamSize): Lobby {
834	  return { teamSize, teams: [], players: {}, spectators: [] };
835	}
836	
837	export function slotOf(lobby: Lobby, id: string): Slot | null {
838	  for (let t = 0; t < lobby.teams.length; t++) {
839	    const members = lobby.teams[t];
840	    if (!members) continue;
841	    const i = members.indexOf(id);
842	    if (i >= 0) {
843	      const role = ROLES[i];
844	      if (role) return { team: t, role, index: i };
845	    }
846	  }
847	  return null;
848	}
849	
850	export function controlsFor(lobby: Lobby, id: string): ControlSet | null {
851	  const slot = slotOf(lobby, id);
852	  if (!slot) return null;
853	  const size = lobby.teams[slot.team]?.length ?? 0;
854	  if (size === 1) return { steer: true, gas: false, aim: false, fire: true, powers: true, bail: false, solo: true };
855	  if (slot.role === 'pilot') return { steer: true, gas: true, aim: false, fire: false, powers: false, bail: false, solo: false };
856	  if (slot.role === 'gunner') {
857	    // 2-person team: the Gunner also gets the two power buttons; bailing is automatic.
858	    return { steer: false, gas: false, aim: true, fire: true, powers: size === 2, bail: false, solo: false };
859	  }
860	  return { steer: false, gas: false, aim: false, fire: false, powers: true, bail: true, solo: false };
861	}
862	
863	function clone(lobby: Lobby): Lobby {
864	  const players: Record<string, LobbyPlayer> = {};
865	  for (const [id, p] of Object.entries(lobby.players)) players[id] = { ...p };
866	  return {
867	    teamSize: lobby.teamSize,
868	    teams: lobby.teams.map((m) => [...m]),
869	    players,
870	    spectators: [...lobby.spectators],
871	  };
872	}
873	
874	function joinOrderOf(lobby: Lobby, id: string): number {
875	  return lobby.players[id]?.joinOrder ?? Number.MAX_SAFE_INTEGER;
876	}
877	
878	/** Unpinned first, then most recent joiners first. */
879	function moverPriority(lobby: Lobby, a: string, b: string): number {
880	  const pa = lobby.players[a]?.pinned ? 1 : 0;
881	  const pb = lobby.players[b]?.pinned ? 1 : 0;
882	  if (pa !== pb) return pa - pb;
883	  return joinOrderOf(lobby, b) - joinOrderOf(lobby, a);
884	}
885	
886	/**
887	 * Re-establish the invariants with the fewest moves:
888	 *  1. demote the most recent joiners beyond capacity to spectators, promote spectators into free capacity;
889	 *  2. the balanced size multiset is matched to teams by current size (largest keeps largest), so only surplus people move;
890	 *  3. surplus teams give up unpinned, most recent joiners first; dissolved teams are the smallest with the fewest pins;
891	 *  4. deficits are filled in team order, earliest joiners first; a moved player takes the next free role.
892	 * Each person who moves does so exactly once, which is the minimum for the chosen target multiset.
893	 */
894	export function rebalance(input: Lobby): LobbyChange {
895	  const lobby = clone(input);
896	  const moves: Move[] = [];
897	  const cap = capacity(lobby.teamSize);
898	
899	  interface Work {
900	    orig: number;
901	    members: string[];
902	    target: number;
903	  }
904	  const work: Work[] = lobby.teams.map((members, orig) => ({ orig, members, target: 0 }));
905	  let active = work.reduce((n, w) => n + w.members.length, 0);
906	  const homeless: { id: string; from: number | null }[] = [];
907	
908	  // 1a. over capacity (team size was lowered): demote most recent joiners.
909	  while (active > cap) {
910	    let best: { w: Work; id: string } | null = null;
911	    for (const w of work) {
912	      for (const id of w.members) {
913	        if (!best || moverPriority(lobby, id, best.id) < 0) best = { w, id };
914	      }
915	    }
916	    if (!best) break;
917	    best.w.members.splice(best.w.members.indexOf(best.id), 1);
918	    lobby.spectators.push(best.id);
919	    moves.push({ id: best.id, from: best.w.orig, to: null });
920	    active--;
921	  }
922	  lobby.spectators.sort((a, b) => joinOrderOf(lobby, a) - joinOrderOf(lobby, b));
923	  // 1b. free capacity: promote spectators in join order.
924	  while (active < cap && lobby.spectators.length > 0) {
925	    const id = lobby.spectators.shift();
926	    if (id === undefined) break;
927	    homeless.push({ id, from: null });
928	    active++;
929	  }
930	
931	  // 2. targets by current size: largest team keeps the largest target.
932	  const targets = targetSizes(active, lobby.teamSize);
933	  const pinnedCount = (w: Work): number => w.members.filter((id) => lobby.players[id]?.pinned).length;
934	  const order = [...work].sort((a, b) => b.members.length - a.members.length || pinnedCount(b) - pinnedCount(a) || a.orig - b.orig);
935	  while (work.length < targets.length) {
936	    const w: Work = { orig: -1, members: [], target: 0 };
937	    work.push(w);
938	    order.push(w);
939	  }
940	  for (let i = 0; i < order.length; i++) {
941	    const w = order[i];
942	    if (w) w.target = targets[i] ?? 0; // beyond the target count: dissolved
943	  }
944	
945	  // 3. surplus leaves (dissolved teams have target 0 so everybody leaves).
946	  for (const w of work) {
947	    while (w.members.length > w.target) {
948	      const sorted = [...w.members].sort((a, b) => moverPriority(lobby, a, b));
949	      const id = sorted[0];
950	      if (id === undefined) break;
951	      w.members.splice(w.members.indexOf(id), 1);
952	      homeless.push({ id, from: w.orig });
953	    }
954	  }
955	
956	  // 4. fill deficits in team order, earliest joiners first.
957	  homeless.sort((a, b) => joinOrderOf(lobby, a.id) - joinOrderOf(lobby, b.id));
958	  const kept = work.filter((w) => w.target > 0);
959	  for (const w of kept) {
960	    while (w.members.length < w.target && homeless.length > 0) {
961	      const h = homeless.shift();
962	      if (!h) break;
963	      w.members.push(h.id);
964	      moves.push({ id: h.id, from: h.from, to: w.orig }); // fixed up below
965	    }
966	  }
967	  // anything left over (should not happen) goes to spectators
968	  for (const h of homeless) {
969	    lobby.spectators.push(h.id);
970	    moves.push({ id: h.id, from: h.from, to: null });
971	  }
972	
973	  // compact and renumber
974	  const finalIndex = new Map<number, number>();
975	  let renumbered = false;
976	  kept.forEach((w, i) => {
977	    if (w.orig >= 0) {
978	      finalIndex.set(w.orig, i);
979	      if (w.orig !== i) renumbered = true;
980	    }
981	  });
982	  lobby.teams = kept.map((w) => w.members);
983	  // `to` was recorded as orig index (or -1 for a new team): translate to the final index.
984	  for (const m of moves) {
985	    if (m.to === null) continue;
986	    if (m.to >= 0) m.to = finalIndex.get(m.to) ?? m.to;
987	    else m.to = kept.findIndex((w) => w.members.includes(m.id));
988	  }
989	  return { lobby, moves, renumbered };
990	}
991	
992	export function joinPlayer(input: Lobby, player: LobbyPlayer): LobbyChange {
993	  const lobby = clone(input);
994	  if (lobby.players[player.id]) return reconnectPlayer(lobby, player.id, player.name);
995	  lobby.players[player.id] = { ...player, pinned: false };
996	  lobby.spectators.push(player.id); // rebalance promotes it if there is room
997	  return rebalance(lobby);
998	}
999	
1000	/** Same token comes back: same slot, same role. */
1001	export function reconnectPlayer(input: Lobby, id: string, name?: string): LobbyChange {
1002	  const lobby = clone(input);
1003	  const p = lobby.players[id];
1004	  if (!p) return { lobby, moves: [], renumbered: false };
1005	  p.connected = true;
1006	  if (name) p.name = name;
1007	  return { lobby, moves: [], renumbered: false };
1008	}
1009	
1010	/** Lobby phase only: the player is gone for good and the teams close up. */
1011	export function leavePlayer(input: Lobby, id: string): LobbyChange {
1012	  const lobby = clone(input);
1013	  if (!lobby.players[id]) return { lobby, moves: [], renumbered: false };
1014	  for (const members of lobby.teams) {
1015	    const i = members.indexOf(id);
1016	    if (i >= 0) members.splice(i, 1);
1017	  }
1018	  lobby.spectators = lobby.spectators.filter((s) => s !== id);
1019	  delete lobby.players[id];
1020	  return rebalance(lobby);
1021	}
1022	
1023	/** Countdown or battle: the slot stays, the boat idles, the keyboard can take it. */
1024	export function markDisconnected(input: Lobby, id: string): Lobby {
1025	  const lobby = clone(input);
1026	  const p = lobby.players[id];
1027	  if (p) p.connected = false;
1028	  return lobby;
1029	}
1030	
1031	export function setTeamSize(input: Lobby, size: TeamSize): LobbyChange {
1032	  const lobby = clone(input);
1033	  lobby.teamSize = size;
1034	  return rebalance(lobby);
1035	}
1036	
1037	export function setFlags(
1038	  input: Lobby,
1039	  id: string,
1040	  flags: Partial<Pick<LobbyPlayer, 'enabled' | 'ready' | 'calibrated' | 'name'>>,
1041	): Lobby {
1042	  const lobby = clone(input);
1043	  const p = lobby.players[id];
1044	  if (p) Object.assign(p, flags);
1045	  return lobby;
1046	}
1047	
1048	/** Swap role with a teammate (both become pinned). */
1049	export function swapRoles(input: Lobby, id: string, otherId: string): LobbyChange {
1050	  const lobby = clone(input);
1051	  const a = slotOf(lobby, id);
1052	  const b = slotOf(lobby, otherId);
1053	  if (!a || !b || a.team !== b.team || id === otherId) return { lobby, moves: [], renumbered: false };
1054	  const members = lobby.teams[a.team];
1055	  if (!members) return { lobby, moves: [], renumbered: false };
1056	  members[a.index] = otherId;
1057	  members[b.index] = id;
1058	  const pa = lobby.players[id];
1059	  const pb = lobby.players[otherId];
1060	  if (pa) pa.pinned = true;
1061	  if (pb) pb.pinned = true;
1062	  return { lobby, moves: [], renumbered: false };
1063	}
1064	
1065	/** Move to any team with a free slot (members < teamSize). The mover is pinned; the balancer then fixes sizes around them. */
1066	export function moveToTeam(input: Lobby, id: string, team: number): LobbyChange {
1067	  const lobby = clone(input);
1068	  const from = slotOf(lobby, id);
1069	  const dest = lobby.teams[team];
1070	  if (!dest || dest.length >= lobby.teamSize || (from && from.team === team)) {
1071	    return { lobby, moves: [], renumbered: false };
1072	  }
1073	  if (from) lobby.teams[from.team]?.splice(from.index, 1);
1074	  else lobby.spectators = lobby.spectators.filter((s) => s !== id);
1075	  dest.push(id);
1076	  const p = lobby.players[id];
1077	  if (p) p.pinned = true;
1078	  const result = rebalance(lobby);
1079	  result.moves.unshift({ id, from: from ? from.team : null, to: team });
1080	  return result;
1081	}
1082	
1083	export interface StartCheck {
1084	  ok: boolean;
1085	  problems: string[];
1086	  warnings: string[];
1087	}
1088	
1089	/** The host needs at least 2 teams, each with a connected Pilot. Missing Enable controls only warns: the keyboard can cover. */
1090	export function canStart(lobby: Lobby, minTeams: number = CONFIG.teams.minTeamsToStart): StartCheck {
1091	  const problems: string[] = [];
1092	  const warnings: string[] = [];
1093	  if (lobby.teams.length < minTeams) problems.push(`need ${minTeams} teams, have ${lobby.teams.length}`);
1094	  lobby.teams.forEach((members, t) => {
1095	    const pilot = members[0];
1096	    const p = pilot ? lobby.players[pilot] : undefined;
1097	    if (!p) problems.push(`team ${t} has no Pilot`);
1098	    else if (!p.connected) problems.push(`team ${t}: Pilot ${p.name} is disconnected`);
1099	    for (const id of members) {
1100	      const m = lobby.players[id];
1101	      if (m && m.kind === 'phone' && !m.enabled) warnings.push(`${m.name} has not tapped Enable controls`);
1102	    }
1103	  });
1104	  return { ok: problems.length === 0, problems, warnings };
1105	}
1106	
1107	/** Rematch: same teams, same roles; per-round flags reset. Disconnected players keep their slot. */
1108	export function rematchLobby(input: Lobby): Lobby {
1109	  const lobby = clone(input);
1110	  for (const p of Object.values(lobby.players)) {
1111	    p.ready = false;
1112	    p.calibrated = false;
1113	  }
1114	  return lobby;
1115	}
1116	
1117	/** New lobby: pins cleared, disconnected players dropped, everyone re-seated by join order. */
1118	export function resetLobby(input: Lobby): LobbyChange {
1119	  const fresh = createLobby(input.teamSize);
1120	  const ids = Object.values(input.players)
1121	    .filter((p) => p.connected)
1122	    .sort((a, b) => a.joinOrder - b.joinOrder);
1123	  for (const p of ids) {
1124	    fresh.players[p.id] = { ...p, pinned: false, ready: false, calibrated: false };
1125	    fresh.spectators.push(p.id);
1126	  }
1127	  return rebalance(fresh);
1128	}
1129	
1130	export function activePlayerCount(lobby: Lobby): number {
1131	  return lobby.teams.reduce((n, m) => n + m.length, 0);
1132	}
1133	```
