1136	### `src/sim/rules.ts`
1137	
1138	```ts
1139	/**
1140	 * Match flow, combat rules, respawn, hull water, scoring. Pure functions over
1141	 * plain data; the Sim class calls them and applies the results to GameState
1142	 * and to Rapier. Every time value is sim time in seconds.
1143	 */
1144	import { CONFIG, itemDef } from '@shared/config.ts';
1145	import type { GameConfig, WeaponKind } from '@shared/config.ts';
1146	import type { Vec2 } from '@shared/math.ts';
1147	import type {
1148	  BoatStatus,
1149	  Killer,
1150	  KillFeedEntry,
1151	  LethalKind,
1152	  Phase,
1153	  PlayerState,
1154	  Pose,
1155	  ResultsState,
1156	  SimEvent,
1157	  TeamSize,
1158	  TeamState,
1159	} from '@shared/state.ts';
1160	
1161	// ---------------------------------------------------------------------------
1162	// Match state machine (timers are absolute sim times; pause = do not step)
1163	// ---------------------------------------------------------------------------
1164	
1165	export interface MatchClock {
1166	  phase: Phase;
1167	  phaseEndsAt: number;
1168	}
1169	
1170	export type MatchTransition =
1171	  | { kind: 'none' }
1172	  | { kind: 'battle' }
1173	  | { kind: 'overtime'; teams: number[] }
1174	  | { kind: 'results'; results: ResultsState }
1175	  | { kind: 'lobby' };
1176	
1177	export function lobbyClock(): MatchClock {
1178	  return { phase: 'lobby', phaseEndsAt: 0 };
1179	}
1180	
1181	export function startCountdown(now: number, cfg: GameConfig = CONFIG): MatchClock {
1182	  return { phase: 'countdown', phaseEndsAt: now + cfg.match.countdownSeconds };
1183	}
1184	
1185	export function timeLeft(clock: MatchClock, now: number): number {
1186	  return clock.phase === 'lobby' ? 0 : Math.max(0, clock.phaseEndsAt - now);
1187	}
1188	
1189	/** 3-2-1 beeps: emitted when the whole-second countdown crosses 3, 2, 1. */
1190	export function countdownBeeps(prevLeft: number, left: number, cfg: GameConfig = CONFIG): SimEvent[] {
1191	  const out: SimEvent[] = [];
1192	  const a = Math.ceil(prevLeft);
