1200	/**
1201	 * Advance the phase clock. Call once per sim step after simTime advanced.
1202	 * `teams` and `players` are needed to settle the result when the battle ends.
1203	 */
1204	export function tickMatch(
1205	  clock: MatchClock,
1206	  now: number,
1207	  teams: readonly TeamState[],
1208	  players: Readonly<Record<string, PlayerState>>,
1209	  cfg: GameConfig = CONFIG,
1210	): { clock: MatchClock; transition: MatchTransition; events: SimEvent[] } {
1211	  if (clock.phase === 'lobby' || now < clock.phaseEndsAt) return { clock, transition: { kind: 'none' }, events: [] };
1212	  switch (clock.phase) {
1213	    case 'countdown':
1214	      return {
1215	        clock: { phase: 'battle', phaseEndsAt: clock.phaseEndsAt + cfg.match.battleSeconds },
1216	        transition: { kind: 'battle' },
1217	        events: [{ kind: 'horn' }, { kind: 'phase', phase: 'battle' }],
1218	      };
1219	    case 'battle': {
1220	      const tied = tiedForFirst(teams);
1221	      if (tied.length > 1) {
1222	        return {
1223	          clock: { phase: 'overtime', phaseEndsAt: clock.phaseEndsAt + cfg.match.suddenDeathSeconds },
1224	          transition: { kind: 'overtime', teams: tied },
1225	          events: [{ kind: 'horn' }, { kind: 'phase', phase: 'overtime' }],
1226	        };
1227	      }
1228	      const results = computeResults(teams, players, leaderDecidedBy(teams));
1229	      return finish(clock, results, cfg);
1230	    }
1231	    case 'overtime': {
1232	      const results = decideAfterOvertime(teams, players);
1233	      return finish(clock, results, cfg);
1234	    }
1235	    case 'results':
1236	      return cfg.match.autoReturnToLobby
1237	        ? { clock: lobbyClock(), transition: { kind: 'lobby' }, events: [{ kind: 'phase', phase: 'lobby' }] }
1238	        : { clock, transition: { kind: 'none' }, events: [] };
1239	    default:
1240	      return { clock, transition: { kind: 'none' }, events: [] };
1241	  }
1242	}
