1244	function finish(clock: MatchClock, results: ResultsState, cfg: GameConfig): { clock: MatchClock; transition: MatchTransition; events: SimEvent[] } {
1245	  return {
1246	    clock: { phase: 'results', phaseEndsAt: clock.phaseEndsAt + cfg.match.resultsSeconds },
1247	    transition: { kind: 'results', results },
1248	    events: [{ kind: 'phase', phase: 'results' }, { kind: 'win', team: results.winner }],
1249	  };
1250	}
