1295	export type HitSource =
1296	  | { kind: WeaponKind | 'mine'; team: number; playerId: string | null; pose: Pose }
1297	  | { kind: 'ram'; team: number; playerId: string | null; pose: Pose; attackerBoostUntil: number; impactSpeed: number }
