1300	export type IgnoreReason = 'notAlive' | 'ownTeam' | 'protected' | 'notLethal' | 'attackerNotBoosted' | 'bothBoosted' | 'ramTooSlow';
1301	
1302	export type HitOutcome =
1303	  | { result: 'ignored'; reason: IgnoreReason }
1304	  | { result: 'shielded'; byTeam: number }
1305	  | { result: 'sunk'; killer: Killer };
