1307	/**
1308	 * Order of checks (each one is a test case):
1309	 *  1. target not alive  -> ignored (a sinking boat cannot be killed twice)
1310	 *  2. same team         -> ignored (own shots, splash, mines, rams never hurt you)
1311	 *  3. not lethal        -> ignored (Water Cannon; an unboosted or slow ram; two boosted boats bounce)
1312	 *  4. spawn protection  -> ignored, the Shield is NOT consumed
1313	 *  5. Shield up         -> shielded, Shield consumed
1314	 *  6. otherwise         -> sunk, credited to source.team / source.playerId
1315	 */
1316	export function resolveHit(target: HitTarget, source: HitSource, now: number, cfg: GameConfig = CONFIG): HitOutcome {
1317	  if (target.status !== 'alive') return { result: 'ignored', reason: 'notAlive' };
1318	  if (target.team === source.team) return { result: 'ignored', reason: 'ownTeam' };
1319	  if (source.kind === 'waterCannon') return { result: 'ignored', reason: 'notLethal' };
1320	  if (source.kind === 'ram') {
1321	    const attackerBoosted = now < source.attackerBoostUntil;
1322	    const targetBoosted = now < target.boostUntil;
1323	    if (!attackerBoosted) return { result: 'ignored', reason: 'attackerNotBoosted' };
1324	    if (targetBoosted) return { result: 'ignored', reason: 'bothBoosted' };
1325	    if (source.impactSpeed < cfg.boat.ramMinImpactSpeed) return { result: 'ignored', reason: 'ramTooSlow' };
1326	  }
1327	  if (now < target.protectedUntil) return { result: 'ignored', reason: 'protected' };
1328	  if (now < target.shieldUntil) return { result: 'shielded', byTeam: source.team };
1329	  return {
1330	    result: 'sunk',
1331	    killer: { team: source.team, playerId: source.playerId, weapon: source.kind, pose: { ...source.pose } },
1332	  };
1333	}
