1375	/**
1376	 * Random dock at least minDistanceToEnemy from every enemy boat on the water and
1377	 * not within dockClearance of any boat (or a dock chosen earlier this step).
1378	 * Fallback: the free dock farthest from the nearest enemy; last resort: any dock.
1379	 */
1380	export function pickRespawnDock(
1381	  docks: readonly Dock[],
1382	  enemies: readonly Vec2[],
1383	  occupied: readonly Vec2[],
1384	  rng: () => number,
1385	  cfg: GameConfig = CONFIG,
1386	): Dock | null {
1387	  if (docks.length === 0) return null;
1388	  const minEnemy = (d: Dock): number => enemies.reduce((m, e) => Math.min(m, Math.hypot(e.x - d.x, e.y - d.y)), Infinity);
1389	  const isFree = (d: Dock): boolean => occupied.every((o) => Math.hypot(o.x - d.x, o.y - d.y) >= cfg.respawn.dockClearance);
1390	  const free = docks.filter(isFree);
1391	  const pool = free.length > 0 ? free : [...docks];
1392	  const safe = pool.filter((d) => minEnemy(d) >= cfg.respawn.minDistanceToEnemy);
1393	  if (safe.length > 0) return safe[Math.min(safe.length - 1, Math.floor(rng() * safe.length))] ?? null;
1394	  let best: Dock | null = null;
1395	  let bestDist = -1;
1396	  for (const d of pool) {
1397	    const m = minEnemy(d);
1398	    if (m > bestDist) {
1399	      bestDist = m;
1400	      best = d;
1401	    }
1402	  }
1403	  return best;
1404	}
