1452	/** Returns new team and player records with the kill applied (inputs untouched). */
1453	export function creditKill(
1454	  teams: readonly TeamState[],
1455	  players: Readonly<Record<string, PlayerState>>,
1456	  kill: KillRecord,
1457	): { teams: TeamState[]; players: Record<string, PlayerState> } {
1458	  const nextTeams = teams.map((t) => {
1459	    if (t.index === kill.killerTeam) return { ...t, kills: t.kills + 1, lastKillAt: kill.at };
1460	    if (t.index === kill.victimTeam) return { ...t, deaths: t.deaths + 1 };
1461	    return t;
1462	  });
1463	  const nextPlayers: Record<string, PlayerState> = { ...players };
1464	  const killer = kill.killerPlayer ? nextPlayers[kill.killerPlayer] : undefined;
1465	  if (killer && kill.killerPlayer) {
1466	    nextPlayers[kill.killerPlayer] = {
1467	      ...killer,
1468	      kills: killer.kills + 1,
1469	      bestRamSpeed: kill.weapon === 'ram' ? Math.max(killer.bestRamSpeed, kill.impactSpeed ?? 0) : killer.bestRamSpeed,
1470	    };
1471	  }
1472	  const victim = teams.find((t) => t.index === kill.victimTeam);
1473	  for (const id of victim?.members ?? []) {
1474	    const p = nextPlayers[id];
1475	    if (p) nextPlayers[id] = { ...p, deaths: p.deaths + 1 };
1476	  }
1477	  return { teams: nextTeams, players: nextPlayers };
