1480	/** Kills desc, deaths asc, earliest last kill, lower index. A team that never scored sorts after one that did. */
1481	export function compareTeams(a: TeamState, b: TeamState): number {
1482	  if (a.kills !== b.kills) return b.kills - a.kills;
1483	  if (a.deaths !== b.deaths) return a.deaths - b.deaths;
1484	  const la = a.lastKillAt > 0 ? a.lastKillAt : Infinity;
1485	  const lb = b.lastKillAt > 0 ? b.lastKillAt : Infinity;
1486	  if (la !== lb) return la - lb;
1487	  return a.index - b.index;
1488	}
