1510	/** Still tied after 30 s: the tied team that reached the final score first wins; nobody ever scored -> draw. */
1511	export function decideAfterOvertime(teams: readonly TeamState[], players: Readonly<Record<string, PlayerState>>): ResultsState {
1512	  const tied = tiedForFirst(teams);
1513	  const scored = tied
1514	    .map((i) => teams.find((t) => t.index === i))
1515	    .filter((t): t is TeamState => !!t && t.lastKillAt > 0)
1516	    .sort((a, b) => a.lastKillAt - b.lastKillAt);
1517	  const first = scored[0];
1518	  if (first) return computeResults(teams, players, 'firstToScore', first.index);
