1745	/**
1746	 * Aiming in 2D (SPEC section 4). Aim is one world angle per team; every shot
1747	 * leaves flat along it. These functions are pure: they take the shooter's
1748	 * position, the aim yaw, the enemy candidates and an injected line-of-sight
1749	 * test (a Rapier wall ray in the sim, `() => true` in tests).
1750	 */
1751	import { CONFIG } from '@shared/config.ts';
1752	import type { GameConfig, WeaponKind } from '@shared/config.ts';
1753	import { angleDiff, clamp, DEG, wrapAngle } from '@shared/math.ts';
1754	import type { CrosshairState } from '@shared/state.ts';
1755	
1756	export interface AimCandidate {
1757	  team: number;
1758	  x: number;
1759	  y: number;
1760	  /** Inside smoke: invisible to assist, diamond and locks. */
1761	  hidden: boolean;
1762	}
1763	
1764	/** True when nothing solid (walls, bridges piers, poles) lies between a and b. */
1765	export type LineOfSight = (ax: number, ay: number, bx: number, by: number) => boolean;
1766	export const ALWAYS_VISIBLE: LineOfSight = () => true;
1767	
1768	export interface Bearing {
1769	  team: number;
1770	  x: number;
1771	  y: number;
1772	  dist: number;
1773	  /** Signed angle from the aim line to the enemy, radians, positive = anticlockwise. */
1774	  offset: number;
1775	}
1776	
1777	/** Distance along the unit ray (ox, oy) + t (dx, dy) to the first point on the circle, or null. */
1778	export function rayCircleDistance(ox: number, oy: number, dx: number, dy: number, cx: number, cy: number, r: number): number | null {
1779	  const fx = ox - cx;
1780	  const fy = oy - cy;
1781	  const b = 2 * (fx * dx + fy * dy);
1782	  const c = fx * fx + fy * fy - r * r;
1783	  const disc = b * b - 4 * c;
1784	  if (disc < 0) return null;
1785	  const s = Math.sqrt(disc);
1786	  const t0 = (-b - s) / 2;
1787	  if (t0 >= 0) return t0;
1788	  const t1 = (-b + s) / 2;
1789	  return t1 >= 0 ? 0 : null; // origin inside the circle counts as distance 0
1790	}
1791	
1792	export function bearings(ox: number, oy: number, aimYaw: number, candidates: readonly AimCandidate[]): Bearing[] {
1793	  const out: Bearing[] = [];
1794	  for (const c of candidates) {
1795	    if (c.hidden) continue;
1796	    const dx = c.x - ox;
1797	    const dy = c.y - oy;
1798	    const dist = Math.hypot(dx, dy);
1799	    if (dist < 1e-6) continue;
1800	    out.push({ team: c.team, x: c.x, y: c.y, dist, offset: angleDiff(aimYaw, Math.atan2(dy, dx)) });
1801	  }
1802	  return out;
1803	}
1804	
1805	/**
1806	 * Red diamond + gyro slow-down: the aim ray hits an enemy's hull circle within
1807	 * range and with line of sight. `wasOnTarget` enlarges the circle (hysteresis)
1808	 * so the state does not flicker at the hull edge.
1809	 */
1810	export function enemyUnderCrosshair(
1811	  ox: number,
1812	  oy: number,
1813	  aimYaw: number,
1814	  candidates: readonly AimCandidate[],
1815	  wasOnTarget: boolean,
1816	  cfg: GameConfig = CONFIG,
1817	  los: LineOfSight = ALWAYS_VISIBLE,
1818	): number | null {
1819	  const dx = Math.cos(aimYaw);
1820	  const dy = Math.sin(aimYaw);
1821	  const r = wasOnTarget ? cfg.aim.onTargetStickyRadius : cfg.aim.onTargetRadius;
1822	  let best: { team: number; t: number } | null = null;
1823	  for (const c of candidates) {
1824	    if (c.hidden) continue;
1825	    const t = rayCircleDistance(ox, oy, dx, dy, c.x, c.y, r);
1826	    if (t === null || t > cfg.aim.onTargetRange) continue;
1827	    if (best && t >= best.t) continue;
1828	    if (cfg.aim.requireLineOfSight && !los(ox, oy, c.x, c.y)) continue;
1829	    best = { team: c.team, t };
1830	  }
1831	  return best ? best.team : null;
1832	}
1833	
1834	/**
1835	 * Cannon aim assist: among enemies inside the assist cone (smallest angular
1836	 * offset wins, distance breaks ties), bend the shot by at most assistMaxBendDeg.
1837	 */
1838	export function aimAssist(
1839	  ox: number,
1840	  oy: number,
1841	  aimYaw: number,
1842	  candidates: readonly AimCandidate[],
1843	  cfg: GameConfig = CONFIG,
1844	  los: LineOfSight = ALWAYS_VISIBLE,
1845	): { yaw: number; team: number | null } {
1846	  const half = cfg.aim.assistHalfAngleDeg * DEG;
1847	  const maxBend = cfg.aim.assistMaxBendDeg * DEG;
1848	  let best: Bearing | null = null;
1849	  for (const b of bearings(ox, oy, aimYaw, candidates)) {
1850	    if (b.dist > cfg.aim.assistRange || Math.abs(b.offset) > half) continue;
1851	    if (best && (Math.abs(b.offset) > Math.abs(best.offset) || (Math.abs(b.offset) === Math.abs(best.offset) && b.dist >= best.dist))) continue;
1852	    if (cfg.aim.requireLineOfSight && !los(ox, oy, b.x, b.y)) continue;
1853	    best = b;
1854	  }
1855	  if (!best) return { yaw: aimYaw, team: null };
1856	  return { yaw: wrapAngle(aimYaw + clamp(best.offset, -maxBend, maxBend)), team: best.team };
1857	}
1858	
1859	/** Torpedo lock: the NEAREST enemy (by distance) inside the 40 degree cone ahead of the AIM, within lockRange. */
1860	export function torpedoLock(
1861	  ox: number,
1862	  oy: number,
1863	  aimYaw: number,
1864	  candidates: readonly AimCandidate[],
1865	  cfg: GameConfig = CONFIG,
1866	  los: LineOfSight = ALWAYS_VISIBLE,
1867	): number | null {
1868	  const half = cfg.weapons.torpedo.lockHalfAngleDeg * DEG;
1869	  let best: Bearing | null = null;
1870	  for (const b of bearings(ox, oy, aimYaw, candidates)) {
1871	    if (b.dist > cfg.weapons.torpedo.lockRange || Math.abs(b.offset) > half) continue;
1872	    if (best && b.dist >= best.dist) continue;
1873	    if (cfg.aim.requireLineOfSight && !los(ox, oy, b.x, b.y)) continue;
1874	    best = b;
1875	  }
1876	  return best ? best.team : null;
1877	}
