1879	/** Mortar: lands on the nearest enemy within 10 degrees of the aim line and 60 m (walls do not matter), else 40 m ahead. */
1880	export function mortarTarget(
1881	  ox: number,
1882	  oy: number,
1883	  aimYaw: number,
1884	  candidates: readonly AimCandidate[],
1885	  cfg: GameConfig = CONFIG,
1886	): { x: number; y: number; team: number | null } {
1887	  const half = cfg.weapons.mortar.targetHalfAngleDeg * DEG;
1888	  let best: Bearing | null = null;
1889	  for (const b of bearings(ox, oy, aimYaw, candidates)) {
1890	    if (b.dist > cfg.weapons.mortar.targetRange || Math.abs(b.offset) > half) continue;
1891	    if (best && b.dist >= best.dist) continue;
1892	    best = b;
1893	  }
1894	  if (best) return { x: best.x, y: best.y, team: best.team };
1895	  const r = cfg.weapons.mortar.fallbackRange;
1896	  return { x: ox + Math.cos(aimYaw) * r, y: oy + Math.sin(aimYaw) * r, team: null };
1897	}
