1900	 * The sim integrates the phone's dYaw (already dead-zoned and x2 on the phone).
1901	 * The on-target gain lives here because only the sim knows where enemies are.
1902	 */
1903	export function integrateAim(aimYaw: number, dYaw: number, onTarget: boolean, cfg: GameConfig = CONFIG): number {
