2188	/** Pixels with the origin at the BOTTOM-LEFT, for WebGLRenderer.setViewport / setScissor. */
2189	export function toGlPixels(r: Rect, width: number, height: number): PixelRect {
2190	  const x = Math.round(r.x * width);
2191	  const w = Math.round(r.w * width);
2192	  const h = Math.round(r.h * height);
2193	  const yTop = Math.round(r.y * height);
2194	  return { x, y: height - yTop - h, w, h };
