2196	
2197	export function rectAspect(r: Rect, width: number, height: number): number {
2198	  return (r.w * width) / (r.h * height);
2199	}
2200	
2201	/** Does any pair of cells overlap (should never happen)? */
2202	export function cellsOverlap(cells: readonly Rect[]): boolean {
2203	  for (let i = 0; i < cells.length; i++) {
2204	    for (let j = i + 1; j < cells.length; j++) {
2205	      const a = cells[i];
2206	      const b = cells[j];
2207	      if (!a || !b) continue;
2208	      const eps = 1e-9;
2209	      if (a.x + a.w > b.x + eps && b.x + b.w > a.x + eps && a.y + a.h > b.y + eps && b.y + b.h > a.y + eps) return true;
2210	    }
2211	  }
2212	  return false;
2213	}
