2220	/**
2221	 * Keyboard harness: one keyboard plays every role of up to 6 teams.
2222	 * Pure part: harnessInputs() turns the set of pressed KeyboardEvent.code
2223	 * values into the same PilotIn / GunnerIn / EngIn packets a phone sends.
2224	 * DOM part: KeyboardHarness listens on window and calls back for globals.
2225	 *
2226	 * Keys use KeyboardEvent.code (physical position: 'KeyA' is the same key on
2227	 * AZERTY). F1..F6 are intercepted by Chrome outside fullscreen on some
2228	 * platforms, so every F-key has a plain alternative (7 8 9 0 - =) and
2229	 * startFullscreenCapture() asks for fullscreen + navigator.keyboard.lock().
2230	 */
2231	import { CONFIG } from '@shared/config.ts';
2232	import type { GameConfig } from '@shared/config.ts';
2233	import type { EngIn, GunnerIn, PilotIn } from '@shared/protocol.ts';
2234	import { keyboardDYaw } from '../sim/aim.ts';
2235	
2236	export type GlobalAction =
2237	  | 'start'
2238	  | 'pause'
2239	  | 'debugOverlay'
2240	  | 'colliders'
2241	  | 'freeCamera'
2242	  | 'addFakeTeam'
2243	  | 'giveRandomWeapon'
2244	  | 'sinkFocused'
2245	  | 'toggleBots';
2246	
2247	export const KEYS = {
2248	  focusTeam: ['Digit1', 'Digit2', 'Digit3', 'Digit4', 'Digit5', 'Digit6'] as const,
2249	  pilot: { left: 'KeyA', right: 'KeyD', gas: 'KeyW', brake: 'KeyS', calibrate: 'KeyC' },
2250	  gunner: { left: 'ArrowLeft', right: 'ArrowRight', fire: 'Space', recenter: 'KeyR' },
2251	  engineer: { power0: 'KeyQ', power1: 'KeyE', bail: 'KeyB' },
2252	  globals: {
2253	    start: ['Enter'],
2254	    pause: ['KeyP'],
2255	    debugOverlay: ['F1', 'Digit7'],
2256	    colliders: ['F2', 'Digit8'],
2257	    freeCamera: ['F3', 'Digit9'],
2258	    addFakeTeam: ['F4', 'Digit0'],
2259	    giveRandomWeapon: ['F5', 'Minus'],
2260	    sinkFocused: ['F6', 'Equal'],
2261	    toggleBots: ['KeyT'],
2262	  } satisfies Record<GlobalAction, readonly string[]>,
2263	} as const;
2264	
2265	export interface HarnessFrame {
2266	  pilot: PilotIn;
2267	  gunner: GunnerIn;
2268	  engineer: EngIn;
2269	  calibrate: boolean;
2270	}
2271	
2272	/** Pure: pressed codes -> one frame of inputs for the focused team. `edge` = codes that went down this frame (taps). */
2273	export function harnessInputs(
2274	  pressed: ReadonlySet<string>,
2275	  edge: ReadonlySet<string>,
2276	  dt: number,
2277	  cfg: GameConfig = CONFIG,
2278	): HarnessFrame {
2279	  const k = KEYS;
2280	  const steer = (pressed.has(k.pilot.right) ? 1 : 0) - (pressed.has(k.pilot.left) ? 1 : 0);
2281	  const use: 0 | 1 | null = edge.has(k.engineer.power0) ? 0 : edge.has(k.engineer.power1) ? 1 : null;
2282	  return {
2283	    pilot: { t: 'in', role: 'pilot', steer: steer * cfg.steer.sign, gas: pressed.has(k.pilot.gas), brake: pressed.has(k.pilot.brake) },
2284	    gunner: {
2285	      t: 'in',
2286	      role: 'gunner',
2287	      dYaw: keyboardDYaw(pressed.has(k.gunner.left), pressed.has(k.gunner.right), dt, cfg),
2288	      fire: pressed.has(k.gunner.fire),
2289	      recenter: edge.has(k.gunner.recenter),
2290	    },
2291	    engineer: { t: 'in', role: 'engineer', use, shake: pressed.has(k.engineer.bail) ? 1 : 0 },
2292	    calibrate: edge.has(k.pilot.calibrate),
2293	  };
2294	}
2295	
2296	export function globalActionFor(code: string): GlobalAction | null {
2297	  for (const [action, codes] of Object.entries(KEYS.globals) as [GlobalAction, readonly string[]][]) {
2298	    if (codes.includes(code)) return action;
2299	  }
2300	  return null;
2301	}
2302	
2303	export function focusTeamFor(code: string): number | null {
2304	  const i = (KEYS.focusTeam as readonly string[]).indexOf(code);
2305	  return i >= 0 ? i : null;
2306	}
2307	
2308	const HANDLED: ReadonlySet<string> = new Set<string>([
2309	  ...KEYS.focusTeam,
2310	  ...Object.values(KEYS.pilot),
2311	  ...Object.values(KEYS.gunner),
2312	  ...Object.values(KEYS.engineer),
2313	  ...Object.values(KEYS.globals).flat(),
2314	]);
2315	
2316	export interface HarnessCallbacks {
2317	  onGlobal: (action: GlobalAction) => void;
2318	  onFocusTeam: (team: number) => void;
2319	}
2320	
2321	/** DOM side. Call sample(dt) once per render frame and feed the result to the sim for the focused team's slots. */
2322	export class KeyboardHarness {
2323	  readonly pressed = new Set<string>();
2324	  private edge = new Set<string>();
2325	  focusedTeam = 0;
2326	
2327	  constructor(
2328	    private readonly target: Window,
2329	    private readonly callbacks: HarnessCallbacks,
2330	    private readonly cfg: GameConfig = CONFIG,
2331	  ) {}
2332	
2333	  attach(): void {
2334	    this.target.addEventListener('keydown', this.onKeyDown);
2335	    this.target.addEventListener('keyup', this.onKeyUp);
2336	    this.target.addEventListener('blur', this.onBlur);
2337	  }
2338	
2339	  detach(): void {
2340	    this.target.removeEventListener('keydown', this.onKeyDown);
2341	    this.target.removeEventListener('keyup', this.onKeyUp);
2342	    this.target.removeEventListener('blur', this.onBlur);
2343	  }
2344	
2345	  sample(dt: number): HarnessFrame {
2346	    const frame = harnessInputs(this.pressed, this.edge, dt, this.cfg);
2347	    this.edge = new Set();
2348	    return frame;
2349	  }
2350	
2351	  private readonly onKeyDown = (e: KeyboardEvent): void => {
2352	    if (!HANDLED.has(e.code)) return;
2353	    e.preventDefault();
2354	    if (e.repeat) return; // auto-repeat: the key is still in `pressed`
2355	    this.pressed.add(e.code);
2356	    this.edge.add(e.code);
2357	    const team = focusTeamFor(e.code);
2358	    if (team !== null) {
2359	      this.focusedTeam = team;
2360	      this.callbacks.onFocusTeam(team);
2361	      return;
2362	    }
2363	    const action = globalActionFor(e.code);
2364	    if (action) this.callbacks.onGlobal(action);
2365	  };
2366	
2367	  private readonly onKeyUp = (e: KeyboardEvent): void => {
2368	    if (!HANDLED.has(e.code)) return;
2369	    e.preventDefault();
2370	    this.pressed.delete(e.code);
2371	  };
2372	
2373	  private readonly onBlur = (): void => {
2374	    this.pressed.clear(); // never leave GAS stuck when the window loses focus
2375	  };
2376	}
2377	
2378	/**
2379	 * Call from the Start button click (user activation): fullscreen makes Chrome
2380	 * deliver F1..F6 to the page, and the Keyboard Lock API (Chrome, secure
2381	 * context) captures them even where the OS would take them.
2382	 */
2383	export async function startFullscreenCapture(root: HTMLElement): Promise<void> {
2384	  if (!document.fullscreenElement) await root.requestFullscreen();
2385	  const kb = (navigator as Navigator & { keyboard?: { lock?: (codes?: string[]) => Promise<void> } }).keyboard;
2386	  if (kb?.lock) await kb.lock(['F1', 'F2', 'F3', 'F4', 'F5', 'F6']);
2387	}
