2393	```ts
2394	/**
2395	 * Trivial bot: drives toward crates or enemies, fires when lined up, uses
2396	 * powers now and then, bails. It only reads GameState and emits the same
2397	 * packets a phone would, so it tests the whole input path.
2398	 */
2399	import { CONFIG } from '@shared/config.ts';
2400	import type { GameConfig } from '@shared/config.ts';
2401	import { angleDiff, clamp, DEG } from '@shared/math.ts';
2402	import type { EngIn, GunnerIn, PilotIn } from '@shared/protocol.ts';
2403	import type { BoatState, GameState } from '@shared/state.ts';
2404	
2405	export interface BotMemory {
2406	  waypoint: { x: number; y: number } | null;
2407	  stuckSince: number;
2408	  reverseUntil: number;
2409	  nextPowerAt: number;
2410	}
2411	
2412	export interface BotFrame {
2413	  pilot: PilotIn;
2414	  gunner: GunnerIn;
2415	  engineer: EngIn;
2416	  mem: BotMemory;
2417	}
2418	
2419	export function createBot(): BotMemory {
2420	  return { waypoint: null, stuckSince: -1, reverseUntil: 0, nextPowerAt: 0 };
2421	}
2422	
2423	function idleFrame(mem: BotMemory): BotFrame {
2424	  return {
2425	    pilot: { t: 'in', role: 'pilot', steer: 0, gas: false, brake: false },
2426	    gunner: { t: 'in', role: 'gunner', dYaw: 0, fire: false, recenter: false },
2427	    engineer: { t: 'in', role: 'engineer', use: null, shake: 0 },
2428	    mem,
2429	  };
2430	}
2431	
2432	function nearestEnemy(state: GameState, me: BoatState): BoatState | null {
2433	  let best: BoatState | null = null;
2434	  let bestD = Infinity;
2435	  for (const b of state.boats) {
2436	    if (b.team === me.team || b.status !== 'alive') continue;
2437	    const d = Math.hypot(b.pose.x - me.pose.x, b.pose.y - me.pose.y);
2438	    if (d < bestD) {
2439	      bestD = d;
2440	      best = b;
2441	    }
2442	  }
2443	  return best;
2444	}
2445	
2446	function nearestCrate(state: GameState, me: BoatState, category: 'weapon' | 'power' | null): { x: number; y: number } | null {
2447	  let best: { x: number; y: number } | null = null;
2448	  let bestD = Infinity;
2449	  for (const c of state.crates) {
2450	    if (c.contents === null || (category && c.category !== category)) continue;
2451	    const d = Math.hypot(c.x - me.pose.x, c.y - me.pose.y);
2452	    if (d < bestD) {
2453	      bestD = d;
2454	      best = { x: c.x, y: c.y };
2455	    }
2456	  }
2457	  return best;
2458	}
2459	
2460	export function botThink(
2461	  state: GameState,
2462	  team: number,
2463	  memIn: BotMemory,
2464	  dt: number,
2465	  rng: () => number,
2466	  cfg: GameConfig = CONFIG,
2467	): BotFrame {
2468	  const me = state.boats[team];
2469	  const mem: BotMemory = { ...memIn };
2470	  if (!me || me.status !== 'alive' || (state.phase !== 'battle' && state.phase !== 'overtime')) {
2471	    return idleFrame({ ...mem, waypoint: null, stuckSince: -1 });
2472	  }
2473	  const now = state.simTime;
2474	  const b = cfg.bots;
2475	  const enemy = nearestEnemy(state, me);
2476	  const enemyDist = enemy ? Math.hypot(enemy.pose.x - me.pose.x, enemy.pose.y - me.pose.y) : Infinity;
2477	
2478	  // --- waypoint: a weapon crate when unarmed, otherwise the enemy, otherwise any crate
2479	  const reached = mem.waypoint && Math.hypot(mem.waypoint.x - me.pose.x, mem.waypoint.y - me.pose.y) < b.waypointReached;
2480	  if (!mem.waypoint || reached || rng() < dt * 0.1) {
2481	    mem.waypoint = (me.weapon ? null : nearestCrate(state, me, 'weapon')) ?? (enemy ? { x: enemy.pose.x, y: enemy.pose.y } : null) ?? nearestCrate(state, me, null);
2482	  }
2483	
2484	  // --- stuck detection: slow for stuckSeconds -> reverse for reverseSeconds with the wheel flipped
2485	  if (me.speed < b.stuckSpeed) {
2486	    if (mem.stuckSince < 0) mem.stuckSince = now;
2487	    else if (now - mem.stuckSince > b.stuckSeconds && now >= mem.reverseUntil) {
2488	      mem.reverseUntil = now + b.reverseSeconds;
2489	      mem.stuckSince = -1;
2490	      mem.waypoint = null;
2491	    }
2492	  } else {
2493	    mem.stuckSince = -1;
2494	  }
2495	
2496	  // --- pilot
2497	  let steer = 0;
2498	  let gas = false;
2499	  let brake = false;

2500	  if (mem.waypoint) {
2501	    const want = Math.atan2(mem.waypoint.y - me.pose.y, mem.waypoint.x - me.pose.x);
2502	    const diff = angleDiff(me.pose.angle, want);
2503	    steer = clamp(diff / (30 * DEG), -1, 1);
2504	    gas = Math.abs(diff) < 110 * DEG;
2505	    brake = !gas;
2506	  }
2507	  if (now < mem.reverseUntil) {
2508	    steer = -steer;
2509	    gas = false;
2510	    brake = true;
2511	  }
2512	
2513	  // --- gunner: turn the aim toward the enemy, fire when lined up and in range
2514	  let dYaw = 0;
2515	  let fire = false;
2516	  if (enemy) {
2517	    const want = Math.atan2(enemy.pose.y - me.pose.y, enemy.pose.x - me.pose.x);
2518	    const diff = angleDiff(me.aimYaw, want);
2519	    const step = b.turnRateDegPerSec * DEG * dt;
2520	    dYaw = clamp(diff, -step, step) * cfg.aim.gyroSign; // undo the sim's sign so the bot turns the right way
2521	    const range = me.weapon ? b.fireRange : cfg.weapons.waterCannon.range;
2522	    fire = enemyDist <= range && Math.abs(diff) <= b.fireHalfAngleDeg * DEG && now >= me.fireReadyAt;
2523	  }
2524	
2525	  // --- engineer: a power every few seconds when it makes sense, shake whenever there is water
2526	  let use: 0 | 1 | null = null;
2527	  if (now >= mem.nextPowerAt) {
2528	    const slot = me.powers[0] ? 0 : me.powers[1] ? 1 : null;
2529	    if (slot !== null) {
2530	      const power = me.powers[slot];
2531	      const wantIt =
2532	        (power === 'shield' && enemyDist < 30) ||
2533	        (power === 'boost' && enemyDist < 45) ||
2534	        (power === 'mine' && enemyDist < 25) ||
2535	        power === 'smoke' ||
2536	        power === 'wave';
2537	      if (wantIt) {
2538	        use = slot;
2539	        mem.nextPowerAt = now + b.powerUseInterval;
2540	      }
2541	    }
2542	  }
2543	
2544	  return {
2545	    pilot: { t: 'in', role: 'pilot', steer: steer * cfg.steer.sign, gas, brake },
2546	    gunner: { t: 'in', role: 'gunner', dYaw, fire, recenter: false },
2547	    engineer: { t: 'in', role: 'engineer', use, shake: me.water > 0 ? 1 : 0 },
2548	    mem,
2549	  };
2550	}
