export type SceneMsg = Hud | Evt | LobbySnapshot | { t: 'kick'; reason: string };

// ---------------------------------------------------------------------------
// Relay control: room creation and joining.
// ---------------------------------------------------------------------------

export interface HostRequest {
  v: number;
