export interface InterServerEvents {}

export interface SocketData {
  kind: 'scene' | 'player';
  room: string;
  playerId?: string;
  token?: string;
}

// ---------------------------------------------------------------------------
// Validation helpers used by the relay and the scene. Small, allocation-free.
// ---------------------------------------------------------------------------

export function isRoomCode(s: unknown): s is string {
  return typeof s === 'string' && /^[A-Z]{4}$/.test(s);
}

export function isFiniteNumber(n: unknown): n is number {
  return typeof n === 'number' && Number.isFinite(n);
}

/** Shape-check an input packet and clamp its numbers; returns null when malformed. */
export function sanitizeInput(raw: unknown): InputPacket | null {
  if (!raw || typeof raw !== 'object') return null;
  const p = raw as Record<string, unknown>;
  if (p['t'] !== 'in' || !isFiniteNumber(p['seq'])) return null;
  const seq = Math.max(0, Math.floor(p['seq']));
  switch (p['role']) {
    case 'pilot': {
      if (!isFiniteNumber(p['steer'])) return null;
      return { t: 'in', seq, role: 'pilot', steer: Math.max(-1, Math.min(1, p['steer'])), gas: p['gas'] === true, brake: p['brake'] === true };
    }
    case 'gunner': {
      if (!isFiniteNumber(p['dYaw'])) return null;
      const use = p['use'] === 0 || p['use'] === 1 ? p['use'] : null;
      return {
        t: 'in',
        seq,
        role: 'gunner',
        dYaw: Math.max(-Math.PI, Math.min(Math.PI, p['dYaw'])),
        fire: p['fire'] === true,
        recenter: p['recenter'] === true,
        use,
      };
    }
    case 'engineer': {
      if (!isFiniteNumber(p['shake'])) return null;
      const use = p['use'] === 0 || p['use'] === 1 ? p['use'] : null;
      return { t: 'in', seq, role: 'engineer', use, shake: Math.max(0, Math.min(1, p['shake'])) };
    }
    default:
      return null;
  }
}

export function sanitizePhoneMsg(raw: unknown): PhoneMsg | null {
  if (!raw || typeof raw !== 'object') return null;
  const m = raw as Record<string, unknown>;
  switch (m['t']) {
    case 'swap': {
      const out: PhoneMsg = { t: 'swap' };
      if (isFiniteNumber(m['team'])) out.team = Math.floor(m['team']);
      if (m['role'] === 'pilot' || m['role'] === 'gunner' || m['role'] === 'engineer') out.role = m['role'];
      return out;
    }
    case 'ready':
      return { t: 'ready', ready: m['ready'] === true };
    case 'calibrated':
      return { t: 'calibrated' };
    case 'name':
      return typeof m['name'] === 'string' ? { t: 'name', name: m['name'].slice(0, 16) } : null;
    case 'leave':
      return { t: 'leave' };
    default:
      return null;
  }
}

/** Build the join URL the QR encodes. */
export function joinUrl(origin: string, code: string): string {
  return `${origin}/play?room=${encodeURIComponent(code)}`;
}

/**
 * shared/map.ts: the Venice district as one ASCII grid, its legend, parser and
 * coordinate rules.
 *
 * CONTRACT FILE. Physics (src/sim) builds its walls from `parseMap().walls`;
 * the renderer (src/render) builds buildings, bridges and the lagoon from the
 * same cells. Nobody else needs to agree on anything but this file.
 *
 * Coordinate rules
 * ----------------
 * - 8 m per cell, 50 x 38 cells = 400 x 304 m.
 * - Metres, Three.js world frame, Y up, water surface at y = 0.
 * - Map origin at the centre: x = (col - W/2 + 0.5) * 8, z = (row - H/2 + 0.5) * 8.
 *   Row 0 is the far side (negative z); col 0 is the west side (negative x).
 * - The 2D sim uses (x, z). Yaw is Object3D.rotation.y: forward = (-sin yaw, -cos yaw),
 *   yaw 0 points toward -z (up on this map), yaw +PI/2 toward -x (left), positive
 *   yaw turns left. `yawFromDir` and `dirFromYaw` below are the only conversions.
 *
 * Legend
 * ------
 *   B  building (solid wall, 3 to 5 floors)        ~  canal water
 *   =  arched stone bridge (water for physics)     R  the big covered bridge (water for physics)
 *   L  lagoon water (open basin; minimap always reveals boats here)
 *   S  spawn dock (water, next to a quay)          C  crate point (water)
 *   T  bell tower, the campanile (solid)           P  wooden pile cluster (solid, small)
 */

